/**
 * TASK: Complete the onModeChanged method so the label named "text"
 * follows the toggle button named "mode":
 *   - when the toggle is NOT selected the label must read "Good day."
 *   - when the toggle IS selected the label must read "Yo!"
 *
 * Example: clicking the toggle once selects it, so the label becomes "Yo!".
 * Clicking it again deselects it, so the label returns to "Good day.".
 *
 * The components are already created, named, and wired for you.
 */
import java.awt.event.ItemEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToggleButton;

public class ToggleGreetingPanel extends JPanel {

    private final JToggleButton mode = new JToggleButton("Casual");
    private final JLabel text = new JLabel("Good day.");

    public ToggleGreetingPanel() {
        mode.setName("mode");
        text.setName("text");
        add(mode);
        add(text);
        mode.addItemListener(this::onModeChanged);
    }

    private void onModeChanged(ItemEvent e) {
        // TODO: set the label text based on whether mode is selected
    }
}

