public class ToggleGreetingPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            ToggleGreetingPanel panel = new ToggleGreetingPanel();
            java.awt.Component label = find(panel, "text");
            java.awt.Component toggle = find(panel, "mode");
            check("label named text exists", true, label instanceof javax.swing.JLabel);
            check("toggle named mode exists", true, toggle instanceof javax.swing.JToggleButton);
            check("initial label", "Good day.", textOf(label));
            if (toggle instanceof javax.swing.JToggleButton) {
                javax.swing.JToggleButton t = (javax.swing.JToggleButton) toggle;
                t.doClick();
                check("after first click (selected)", "Yo!", textOf(label));
                t.doClick();
                check("after second click (unselected)", "Good day.", textOf(label));
                t.setSelected(true);
                check("after setSelected(true)", "Yo!", textOf(label));
                t.setSelected(false);
                check("after setSelected(false)", "Good day.", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  toggle button not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

