import java.awt.event.ItemEvent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JToggleButton;

public class ToggleGreetingPanel extends JPanel {

    private final JToggleButton mode = new JToggleButton("Casual");
    private final JLabel text = new JLabel("Good day.");

    public ToggleGreetingPanel() {
        mode.setName("mode");
        text.setName("text");
        add(mode);
        add(text);
        mode.addItemListener(this::onModeChanged);
    }

    private void onModeChanged(ItemEvent e) {
        text.setText(mode.isSelected() ? "Yo!" : "Good day.");
    }
}
